POST /admissions/{admission_id}/flowshee.typescript_example:
// Commit Flowsheet Entry: vitals  (permissions: ipd.flowsheet.record)
export const addVitals = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/flowsheet/vitals`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Visible correction entry for a vitals row  (permissions: ipd.flowsheet.record)
export const correctVitals = (admission_id, entry_id, body) =>
  api("POST", `/admissions/${admission_id}/flowsheet/vitals/${entry_id}/correction`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Commit a nursing note  (permissions: ipd.flowsheet.record)
